/** Columns a run of notes actually fills: notes whose left edges match share a column. */
const used = (el: HTMLElement) => new Set([...el.children].map((c) => Math.round(c.getBoundingClientRect().left))).size

/**
 * CSS gives each run min(columns the sheet allows, notes in the run) columns, but a tall note can leave a column empty.
 * Start each run from its full note count and lower it until every column holds a note.
 */
export function fitRuns(root: ParentNode) {
  for (const el of root.querySelectorAll<HTMLElement>('[data-cols][data-n]')) {
    el.style.setProperty('--n', el.dataset.n!)
    for (let k = 0; k < 3; k++) {
      const cols = parseInt(getComputedStyle(el).columnCount) || 1
      const n = used(el)
      if (n >= cols) break
      el.style.setProperty('--n', String(n))
    }
  }
}
